import sys
from collections import defaultdict, deque

input = sys.stdin.readline

def read_ints():
    return list(map(int, input().split()))

def read_int():
    return int(input())

def read_ints_str():
    return input().split()

def main():
    N, M = read_ints()
    parent = read_ints()
    owner = read_ints()
    thresholds = read_ints()
    Q = read_int()

    # Build the tree
    tree = defaultdict(list)
    for i in range(1, N):
        tree[parent[i-1]-1].append(i)

    # Process donations
    donations = [0] * N
    for _ in range(Q):
        F, X, D = read_ints()
        F -= 1  # Convert to 0-based index
        queue = deque([F])
        depth = 0
        while queue:
            for _ in range(len(queue)):
                node = queue.popleft()
                donations[node] += X + depth * D
                for child in tree[node]:
                    queue.append(child)
            depth += 1

    # Check thresholds
    results = []
    for i in range(M):
        total_earned = 0
        for j in range(N):
            if owner[j] == i + 1:
                total_earned += donations[j]
        if total_earned >= thresholds[i]:
            results.append(1)
        else:
            results.append("rekt")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
